function scenarioMatches(p){return state.scenario==='all'||p.system||(state.scenario==='dev'?p.tags.some(t=>['研发','设计','TypeScript','React'].includes(t)):state.scenario==='ops'?p.tags.some(t=>['运维','生产','服务'].includes(t)):p.tags.some(t=>['网络','边缘','运维'].includes(t)));}

const nodeById = id => state.nodes.find(n=>n.id===id);
const children = (parent,nodes=state.nodes) => nodes.filter(n=>n.parent===parent).sort((a,b)=>a.order-b.order);
const app = document.querySelector('#app');
const overlay = document.querySelector('#overlay');
function toast(text){const el=document.querySelector('#toast');el.textContent=text;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),3200);}
function snapshot(){return structuredClone({nodes:state.nodes,tabs:state.tabs,favorites:state.favorites,memories:state.memories,projects,sessions,aiSessions:state.aiSessions,skills:state.skills,activeSession:state.activeSession,aiProject:state.aiProject});}
function mutate(label,fn){state.history.push({label,data:snapshot()});if(state.history.length>30)state.history.shift();fn();state.version++;closeMenu();render();toast(label+' · 可撤销');}
function undo(){const entry=state.history.pop();if(!entry)return toast('还没有需要撤销的操作');const {projects:oldProjects,sessions:oldSessions,...saved}=entry.data;projects.splice(0,projects.length,...oldProjects);sessions.splice(0,sessions.length,...oldSessions);Object.assign(state,saved);if(!state.tabs.some(t=>t.id===state.tab))state.tab='favorites';state.version++;render();toast('已撤销：'+entry.label);}
function isDescendant(candidate,id){let node=nodeById(candidate);const seen=new Set();while(node){if(node.id===id)return true;if(seen.has(node.id))return true;seen.add(node.id);node=nodeById(node.parent);}return false;}
function canMove(id,parent){const n=nodeById(id),p=nodeById(parent);return !!n && !n.system && !p?.system && !isDescendant(parent,id) && (parent===null||p?.kind==='category'||(p?.kind==='project'&&n.kind==='workspace'));}
function moveNode(id,parent,before){if(!canMove(id,parent))return toast('这个位置不能接收该节点');mutate('已移动节点',()=>{const n=nodeById(id);n.parent=parent;const siblings=children(parent).filter(x=>x.id!==id);const index=before?siblings.findIndex(x=>x.id===before):-1;siblings.splice(index<0?siblings.length:index,0,n);siblings.forEach((x,i)=>x.order=i);if(parent)state.collapsed.delete(parent);});}
function sortNode(id,dir){const node=nodeById(id);if(!node)return;const siblings=children(node.parent),idx=siblings.indexOf(node);let next=dir==='top'?0:dir==='bottom'?siblings.length-1:idx+(dir==='up'?-1:1);next=Math.max(0,Math.min(next,siblings.length-1));if(next===idx)return toast('已经在边界位置');mutate('已调整排序',()=>{siblings.splice(idx,1);siblings.splice(next,0,node);siblings.forEach((x,i)=>x.order=i);});}
function button(action,text,iconName,attrs='',className='btn'){return `<button class="${className}" data-action="${action}" ${attrs}>${iconName?icon(iconName):''}${text}</button>`;}
function iconButton(action,name,label,attrs=''){return `<button class="icon-btn" data-action="${action}" aria-label="${esc(label)}" title="${esc(label)}" ${attrs}>${icon(name)}</button>`;}
function nativeNodes(){return projects.flatMap((p,i)=>[{id:'native-'+p.id,kind:'project',name:p.name,project:p.id,parent:null,order:i},...p.instances.map((h,j)=>({id:'native-'+p.id+'-'+h,kind:'workspace',name:hostById(h).name,project:p.id,host:h,parent:'native-'+p.id,order:j}))]);}
function treeRows(parent=null,depth=0,nodes=state.nodes){return children(parent,nodes).map(n=>{
  if(n.hidden&&!state.showHidden)return '';
  if(n.flat&&!state.showHidden)return treeRows(n.id,depth,nodes);
  const kids=children(n.id,nodes),closed=state.collapsed.has(n.id),host=n.host?hostById(n.host):null;
  return `<div class="tree-row ${n.hidden?'hidden-node':''}" style="--depth:${Math.min(depth,7)}" data-node="${esc(n.id)}" ${state.mode==='custom'&&!n.system?'draggable="true"':''}>
    ${kids.length?`<button class="icon-btn" style="width:15px;height:24px" data-action="collapse" data-id="${esc(n.id)}" aria-label="${closed?'展开':'收起'} ${esc(n.name)}">${icon(closed?'right':'down','chevron')}</button>`:'<span style="width:15px;flex-shrink:0"></span>'}
    ${icon(n.kind==='category'?'folder':n.kind==='workspace'?'branch':'project','tree-icon')}
    <button class="tree-label" data-action="node-open" data-id="${esc(n.id)}" title="${esc(n.name)}">${esc(n.name)}${n.flat?' <span class="source-tag">已合并层级</span>':''}</button>
    ${n.system?'<span class="source-tag">默认</span>':''}${host?`<span class="dot host-dot ${host.online?'':'off'}" title="${esc(host.name)}"></span>`:''}
    ${state.mode==='custom'&&!n.system?`<button class="icon-btn row-menu" data-action="node-menu" data-id="${esc(n.id)}" aria-label="操作 ${esc(n.name)}">${icon('more')}</button>`:''}
  </div>${!closed?treeRows(n.id,depth+1,nodes):''}`;
}).join('');}
function sidebar(){return `<aside class="sidebar">
  <div class="brand"><span class="brand-mark">${icon('logo')}</span><div><span class="brand-name">Paseo</span><small>PERSONAL WORKSPACE</small></div><button class="icon-btn mobile-menu" data-action="mobile-menu" aria-label="关闭导航">${icon('close')}</button></div>
  <nav class="main-nav" aria-label="主导航">
    ${[['home','home','工作台'],['ai','sparkle','AI 工作空间'],['hosts','server','我的 Hosts'],['memory','memory','个人记忆'],['skills','grid','技能中心']].map(([page,ic,label])=>`<button class="nav-button ${state.page===page?'active':''}" data-action="navigate" data-page="${page}">${icon(ic)}<span>${label}</span><span class="count">${page==='ai'?'默认':page==='hosts'?'3 / 4':page==='skills'?skillCount():page==='memory'?memoryCount():''}</span></button>`).join('')}
  </nav>
  <div class="section-label"><span>项目空间</span>${iconButton('new-folder','plus','新建分类')}${iconButton('tree-menu','more','更多树操作')}</div>
  <div class="view-toggle"><button class="${state.mode==='custom'?'active':''}" data-action="view-mode" data-mode="custom">自定义</button><button class="${state.mode==='native'?'active':''}" data-action="view-mode" data-mode="native">原生视图</button></div>
  <div class="tree-toolbar"><button data-action="show-hidden">${icon(state.showHidden?'hide':'eye')}${state.showHidden?'退出管理':'显示隐藏'}</button><button data-action="save-snapshot">${icon('clock')}快照</button><button data-action="undo" aria-label="撤销树操作">${icon('undo')}</button></div>
  <div class="tree" role="navigation" aria-label="项目分类树">${treeRows(null,0,state.mode==='native'?nativeNodes():state.nodes)}<div class="tree-caption">${state.mode==='native'?'原生视图 · 自定义配置已保留':state.showHidden?'管理隐藏节点与合并容器':'拖动整理 · 菜单提供更多操作'}</div></div>
  <div class="sidebar-bottom"><button class="system-location" data-action="system-directory">${icon('folder')}<span><strong>默认 AI 目录</strong><small>~/.paseo/workbench</small></span>${icon('right')}</button><div class="profile"><span class="avatar">ME</span><div class="grow"><strong>个人空间</strong><small>本地优先 · 演示模式</small></div>${iconButton('help','settings','原型使用说明')}</div></div>
</aside>`;}
function topbar(){const title={home:'工作台',ai:'AI 工作空间',hosts:'我的 Hosts',memory:'个人记忆',skills:'技能中心'}[state.page];return `<header class="topbar"><div class="breadcrumb">${iconButton('mobile-menu','menu','打开导航')}<span>个人空间</span>${icon('right')}<strong>${title}</strong></div><div class="top-actions"><select id="scenario-select" aria-label="工作场景" class="top-select">${[['all','全部场景'],['dev','项目研发'],['ops','集群运维'],['review','环境检修']].map(([v,t])=>`<option value="${v}" ${state.scenario===v?'selected':''}>${t}</option>`).join('')}</select><span class="host-summary"><span class="dot"></span>3 / 4 在线</span>${button('skins',skins.find(s=>s.id===state.skin).name,'settings','','btn small skin-trigger')}${button('navigate','AI 工作空间','sparkle','data-page="ai"','btn primary small')}<span class="avatar">ME</span></div></header>`;}
function searchBox(cls=''){return `<div class="search-wrap ${cls}"><form class="search-box" id="global-search" role="search">${icon('search')}<input id="search-input" aria-label="搜索项目、对话、服务器" autocomplete="off" placeholder="搜索项目、对话、Host，或输入一个想法…" value="${esc(state.query)}"><span class="kbd">⌘ K</span><button class="search-go" type="submit" aria-label="搜索">搜索 ${icon('arrow')}</button></form><div class="search-results" id="search-results" hidden></div></div>`;}
function searchScopes(){return `<div class="search-scopes" role="group" aria-label="搜索范围">${[['all','全部'],['project','项目'],['session','对话'],['host','服务器'],['memory','记忆']].map(([id,label])=>`<button class="${state.searchScope===id?'active':''}" data-action="search-scope" data-id="${id}">${label}</button>`).join('')}</div>`;}
function tabBar(){return `<div class="tabs" role="tablist" aria-label="项目集合">${state.tabs.map(t=>`<button class="tab ${state.tab===t.id?'active':''}" role="tab" aria-selected="${state.tab===t.id}" data-action="tab" data-id="${esc(t.id)}">${icon(t.icon||'folder')}${esc(t.name)}</button>`).join('')}${iconButton('new-tab','plus','添加自定义 Tab')}</div>`;}
function shownProjects(){const tab=state.tabs.find(t=>t.id===state.tab);let list;if(tab?.type==='host')list=projects.filter(p=>p.instances.includes(tab.id));else if(tab?.type==='manual')list=(tab.projects||[]).map(projectById).filter(Boolean);else list=state.favorites.map(projectById).filter(Boolean);return list.filter(scenarioMatches);}
function projectCard(p){const host=hostById(p.instances[0]);return `<article class="project-card ${p.system?'system-card':''}" role="button" tabindex="0" data-action="project" data-id="${p.id}" aria-label="打开 ${esc(p.name)}"><div class="card-top"><span class="project-icon ${p.color}">${p.system?icon('sparkle'):esc(p.symbol)}</span><div class="grow"><h3>${esc(p.name)}</h3><p>${p.system?'系统默认项目 · 常驻工作空间':esc(p.desc)}</p></div>${p.system?'<span class="pill accent">DEFAULT</span>':`<button class="icon-btn card-star ${state.favorites.includes(p.id)?'on':''}" data-action="favorite" data-id="${p.id}" aria-label="${state.favorites.includes(p.id)?'取消收藏':'收藏'} ${esc(p.name)}">${icon('star')}</button>`}</div><div class="project-path" title="${esc(resourcePath(p,host.id))}">${icon('folder')}<span>${esc(resourcePath(p,host.id))}</span>${p.instances.length>1?`<span class="path-more">+${p.instances.length-1}</span>`:''}</div><div class="card-tags"><span class="pill"><span class="dot ${p.instances.every(h=>!hostById(h).online)?'off':''}"></span>${p.instances.length>1?p.instances.length+' 个 Host':host.name}</span><span class="pill">${p.system?skillCount()+' 项技能':esc(p.branch)}</span></div><div class="card-footer"><span>${p.system?state.aiSessions.filter(s=>s.project==='assistant').length+' 个会话 · 随时继续':p.count+' 个工作区'}</span><span class="open-label">${p.system?'开始对话':'进入项目'} ${icon('arrow')}</span></div></article>`;}
function activityList(){return `<section class="activity"><div class="section-heading"><h2>接着上次的思路</h2><span class="muted" style="font-size:12px">最近的对话</span></div><div class="activity-list">${sessions.map(s=>`<button class="activity-row" data-action="session" data-id="${s.id}">${icon('chat')}<span class="grow"><strong>${esc(s.title)}</strong><small>${esc(projectById(s.project).name)} <span style="margin:0 5px">/</span> ${hostById(s.host).name}</small></span><time>${s.time}</time>${icon('right')}</button>`).join('')}</div></section>`;}
function VariantA(){const tab=state.tabs.find(t=>t.id===state.tab);return `<div class="home"><section class="hero"><div class="eyebrow">YOUR PERSONAL COMMAND CENTER</div><h1>所有工作，在这里继续。</h1><p>找到项目，连接不同 Host，也让 AI 帮你开始下一步。</p></section>${searchBox()}${searchScopes()}<div class="quick-actions">${button('ask','让 AI 创建项目','plus','data-text="在 Dev Server 创建一个「日志分析」项目，并新建工作区和会话"','quick')}${button('ask','继续上次工作','clock','data-text="我们上次讨论到哪里了？"','quick')}${button('ask','检查环境','server','data-text="帮我整理生产环境检查清单"','quick')}</div>${tabBar()}<div class="section-heading"><div><h2>${tab?.type==='favorites'?'我的项目空间':esc(tab?.name||'项目')}</h2><p>${shownProjects().length} 个项目 · ${state.scenario==='all'?'按你的工作方式组织':'当前场景已筛选'}</p></div><div class="row">${button('new-tab','新建 Tab','plus','','btn small')}${button('add-project','添加项目','plus','','btn primary small')}</div></div><div class="project-grid">${shownProjects().map(projectCard).join('')||'<div class="empty">当前筛选没有项目，可切换场景或添加项目。</div>'}</div><div class="home-lower">${activityList()}<section class="workspace-brief"><div class="section-heading"><h2>AI 已经准备好</h2><span class="pill accent">系统工作空间</span></div><p>技能、记忆、会话，都有自己的位置。</p><div class="mini-directory">${icon('folder')}~/.paseo/workbench</div><div class="skill-badges">${state.skills.filter(s=>s.enabled).map(s=>`<button data-action="skill-detail" data-id="${s.id}">${icon('grid')}${esc(s.name)}</button>`).join('')}</div><div class="row">${button('navigate','打开 AI 工作空间','arrow','data-page="ai"','btn small')}${button('navigate','管理技能',null,'data-page="skills"','btn small quiet')}</div></section></div></div>`;}
function spark(value){return `<div class="spark" aria-label="模拟负载 ${value}%">${[9,15,11,20,17,12,23,16,19,14,21,18].map((n,i)=>`<i style="height:${value?Math.max(3,n+(i%3)*value/10):2}px"></i>`).join('')}</div>`;}
function VariantB(){return `<div class="home"><div class="ops-header"><div><div class="eyebrow">OPERATIONS / OVERVIEW</div><h1>一眼，看见全局。</h1><p>按真实执行环境检查资源，保留跨 Host 的项目关联。</p></div>${button('ask','AI 环境巡检','sparkle','data-text="帮我整理生产环境检查清单"','btn primary')}</div><div class="ops-metrics"><div class="ops-metric"><label><span class="dot"></span>在线 Host</label><strong>3 <span class="muted">/ 4</span></strong><p>本地、研发与生产已连接</p></div><div class="ops-metric"><label>${icon('project')}项目实例</label><strong>${projects.reduce((n,p)=>n+p.instances.length,0)}</strong><p>关联到 ${projects.length} 个逻辑项目</p></div><div class="ops-metric"><label>${icon('branch')}工作区</label><strong>${projects.reduce((n,p)=>n+p.count,0)}</strong><p>原型资源目录</p></div><div class="ops-metric alert"><label><span class="dot warn"></span>需要留意</label><strong>1</strong><p>Edge Node 离线 · 缓存 2 小时前</p></div></div>${searchBox('ops-search')}<div class="section-heading ops-view-heading"><div><h2>Host 与项目</h2><p>同一项目可以分布在不同 Host，目录与会话分别保留。</p></div><div class="segmented"><button class="${state.opsMode==='matrix'?'active':''}" data-action="ops-mode" data-id="matrix">${icon('grid')}Host 矩阵</button><button class="${state.opsMode==='table'?'active':''}" data-action="ops-mode" data-id="table">${icon('menu')}状态列表</button></div></div>${state.opsMode==='matrix'?hostMatrix():hostTable()}<div class="ops-lower"><div class="info-panel"><span class="attention-icon">${icon('server')}</span><div class="grow"><h3>Edge Node 当前离线</h3><p>可以浏览缓存。执行前需要恢复目标 Host 的连接。</p></div>${button('host','查看详情','arrow','data-id="edge"','btn small')}</div><div class="info-panel"><span class="attention-icon">${icon('memory')}</span><div class="grow"><h3>运行约定</h3><p>生产变更前核实 Host、项目与工作目录。</p></div>${button('navigate','查看记忆','arrow','data-page="memory"','btn small')}</div></div></div>`;}
function hostMatrix(){return `<div class="host-matrix">${hosts.map(h=>`<section class="host-column ${h.online?'':'offline'}"><button class="host-column-head" data-action="host" data-id="${h.id}"><span class="host-glyph">${icon('server')}</span><span class="grow"><strong>${h.name}</strong><small><span class="dot ${h.online?'':'off'}"></span>${h.online?h.network:'离线 · 缓存 2 小时前'}</small></span><span class="pill">${h.env}</span></button><div class="host-resources">${projects.filter(p=>p.instances.includes(h.id)&&scenarioMatches(p)).map(p=>`<button class="host-project" data-action="project" data-id="${p.id}"><div class="row"><span class="project-icon ${p.color}">${p.system?icon('sparkle'):esc(p.symbol)}</span><strong>${esc(p.name)}</strong></div><div class="host-path" title="${esc(resourcePath(p,h.id))}">${esc(resourcePath(p,h.id))}</div><div class="row between"><span class="muted">${esc(p.branch)}</span><span>${p.system?'默认':'共 '+p.count+' 工作区'}</span></div></button>`).join('')}</div><button class="host-add" data-action="ask" data-text="在 ${h.name} 创建一个「新项目」项目">${icon('plus')}通过 AI 创建项目</button></section>`).join('')}</div>`;}
function hostTable(){return `<div class="table-wrap"><table class="ops-table"><thead><tr><th>HOST / ENVIRONMENT</th><th>连接状态</th><th class="optional">模拟 CPU</th><th>项目</th><th>资源路径</th><th></th></tr></thead><tbody>${hosts.map(h=>`<tr tabindex="0" role="button" data-action="host" data-id="${h.id}" aria-label="查看 ${h.name}"><td><strong>${h.name}</strong><small>${h.network}</small></td><td><span class="pill"><span class="dot ${h.online?'':'off'}"></span>${h.online?'在线':'离线缓存'}</span></td><td class="optional">${spark(h.cpu)}</td><td>${projects.filter(p=>p.instances.includes(h.id)).length}</td><td class="mono">${h.path}</td><td>${icon('right')}</td></tr>`).join('')}</tbody></table></div>`;}
function chatMessages(){if(!currentSession().messages.length)return `<div class="chat-empty"><div class="hero-symbol">${icon('sparkle')}</div><h3>从一个想法，到一个工作空间。</h3><p>我在「个人 AI」项目中工作。<br>可以帮你整理上下文，也可以准备新项目与会话。</p>${['在 Dev Server 创建一个「日志分析」项目，并新建工作区和会话','在 Paseo Toolkit 下创建工作区「接口联调」','在个人 AI 创建会话「发布计划」'].map(t=>`<button class="suggestion" data-action="ask" data-text="${esc(t)}">${esc(t)} ${icon('arrow')}</button>`).join('')}</div>`;return currentSession().messages.map((m,i)=>m.role==='user'?`<div class="message user">${esc(m.text)}</div>`:`<div class="message assistant"><div class="message-label">${icon('sparkle')} PASEO ASSISTANT <span class="pill">模拟回复</span></div><div class="message-text">${esc(m.text)}</div>${m.plan?planCard(m.plan):''}${m.source?`<button class="source-card" data-action="session" data-id="${m.source}">↗ ${esc(sessions.find(s=>s.id===m.source)?.title)}<small>演示对话来源</small></button>${button('save-memory',m.saved?'已加入个人记忆':'存为记忆候选','memory',`data-index="${i}" ${m.saved?'disabled':''}`,'btn small memory-save')}`:''}</div>`).join('');}
function chatPanel(inline=false){const session=currentSession();return `<div class="${inline?'focus-chat':'assistant-drawer'}" ${inline?'':'role="dialog" aria-modal="true" aria-label="AI 助手"'}><div class="assistant-head"><div class="row">${icon('sparkle')}<div><strong>${esc(session.title)}</strong><small>${esc(projectById(session.project).name)} / ${esc(session.workspace)} · ${hostById(session.host).name}</small></div></div>${inline?'<span class="pill accent">模拟 AI</span>':iconButton('close-drawer','close','关闭 AI 助手')}</div><div class="chat-context"><span>引用项目</span><select id="ai-context" aria-label="AI 项目上下文">${projects.map(p=>`<option value="${p.id}" ${state.aiProject===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select><button data-action="context-preview" class="pill">${skillCount()} 技能 · ${memoryCount()} 记忆 ${icon('right')}</button></div><div class="chat-messages">${chatMessages()}</div><form class="chat-compose" id="chat-form"><div class="compose-box"><textarea id="chat-input" aria-label="向 AI 助手提问" placeholder="说说要做什么，例如：在 Dev Server 创建项目「日志分析」"></textarea><button type="submit" aria-label="发送问题">${icon('up')}</button></div><p>交互演示 · 生成方案后可编辑并模拟创建</p></form></div>`;}
function aiWorkspace(){const session=currentSession();return `<div class="home ai-home"><div class="page-heading"><div><div class="eyebrow">PERSONAL AI / DEFAULT WORKSPACE</div><h1>你的 AI，有自己的工作空间。</h1><p>系统默认项目 · 默认工作空间 · 配置 Host：Local Mac</p></div>${button('system-directory','系统目录','folder','','btn')}</div><div class="ai-layout"><aside class="session-rail"><div class="section-heading"><h2>会话</h2>${iconButton('new-chat','plus','新建 AI 会话')}</div>${state.aiSessions.map(s=>`<button class="session-item ${s.id===session.id?'active':''}" data-action="ai-session" data-id="${s.id}">${icon('chat')}<span><strong>${esc(s.title)}</strong><small>${esc(projectById(s.project).name)} · ${hostById(s.host).name}</small></span></button>`).join('')}<div class="rail-note">每个会话保留所属项目、工作区与 Host。</div></aside>${chatPanel(true)}<aside class="context-rail"><div class="section-heading"><h2>当前工作位置</h2>${icon('folder')}</div><p class="context-name">${esc(projectById(session.project).name)}</p><p>${esc(session.workspace)}</p><code>${esc(session.path)}</code><div class="section-heading"><h2>已启用技能</h2>${button('navigate','管理',null,'data-page="skills"','btn small quiet')}</div>${state.skills.filter(s=>s.enabled).map(s=>`<button class="context-skill" data-action="skill-detail" data-id="${s.id}">${icon('grid')}<span>${esc(s.name)}</span>${icon('right')}</button>`).join('')}<div class="section-heading"><h2>可用记忆</h2><span class="pill">${memoryCount()}</span></div><p>引用已确认、已启用的个人与项目记忆。</p>${button('context-preview','查看本次上下文','memory','','btn small')}<div class="rail-note">创建操作可跨 Host 指定目标；当前会话的执行位置保持明确。</div></aside></div></div>`;}
function skillsPage(){return `<div class="home"><div class="page-heading"><div><div class="eyebrow">SKILLS / EXTEND YOUR ASSISTANT</div><h1>从系统能力，到你的工作习惯。</h1><p>预装常用技能，也为将来的扩展留出位置。</p></div>${button('add-skill','添加自定义技能','plus','','btn primary')}</div><div class="info-box row">${icon('folder')}<span>建议技能目录：<code>~/.paseo/workbench/.agents/skills/</code> · 原型只保存演示定义。</span></div><div class="skill-grid">${state.skills.map(s=>`<article class="skill-card"><div class="row between"><span class="project-icon">${icon('grid')}</span><span class="pill">${s.builtin?'系统预装':'自定义'}</span></div><h2>${esc(s.name)}</h2><p>${esc(s.desc)}</p><code>${esc(s.slug)}/SKILL.md</code><div class="row between">${button('skill-detail','查看详情','arrow',`data-id="${s.id}"`,'btn small quiet')}<button class="toggle ${s.enabled?'on':''}" data-action="toggle-skill" data-id="${s.id}" aria-pressed="${s.enabled}">${s.enabled?'已启用':'已停用'}<span></span></button></div></article>`).join('')}</div></div>`;}
function skillDetail(id){const s=state.skills.find(s=>s.id===id);modal(esc(s.name),s.builtin?'系统预装技能 · 方案预览':'自定义技能 · 演示定义',`<p class="detail-copy">${esc(s.desc)}</p><div class="source-card"><code>${SYSTEM_ROOT}/.agents/skills/${esc(s.slug)}/SKILL.md</code><small>正式接入时由所选 Agent provider 加载技能；当前未创建文件。</small></div><div class="info-box">${s.id==='paseo'?'能力：发现 Host → 选择项目目录 → 创建项目 → 创建工作区 → 启动会话。离线目标不会自动替换为其他 Host。':'技能随个人 AI 工作空间提供上下文，可随时停用或扩展。'}</div>`,button('toggle-skill',s.enabled?'停用技能':'启用技能','check',`data-id="${s.id}"`,'btn primary small'));}
function systemDirectory(){modal('默认 AI 工作目录','建议位于配置 Host（本原型为 Local Mac）；路径可在正式实现时确定。',`<div class="info-box">这是个人 AI 项目与默认工作空间的根目录。以下是目录方案，没有创建真实文件。</div><pre class="directory-tree">${SYSTEM_ROOT}/
├── AGENTS.md             工作空间约定
├── .agents/skills/       可扩展技能
│   ├── paseo/SKILL.md
│   ├── workspace-guide/SKILL.md
│   └── environment-review/SKILL.md
├── memory/              已确认记忆
└── sessions/            会话索引</pre>`,button('navigate','打开技能中心','grid','data-page="skills"','btn primary small'),true);}
function contextPreview(){const p=projectById(state.aiProject);const memories=state.memories.filter(m=>m.confirmed&&m.enabled!==false&&(m.scope==='个人'||m.scope===p?.name));modal('本次引用的上下文','引用范围与会话实际所属位置分别展示。',`<div class="info-box">引用项目：${esc(p?.name)}<br>会话位置：${esc(currentSession().path)}<br>可用技能：${state.skills.filter(s=>s.enabled).map(s=>esc(s.name)).join('、')||'暂无'}</div>${memories.map(m=>`<div class="source-card">${esc(m.title)}<small>${esc(m.text)}</small></div>`).join('')||'<p>当前范围没有启用的记忆。</p>'}`);}
function planCard(p){const offline=!hostById(p.host).online,skill=state.skills.find(s=>s.id==='paseo').enabled;return `<section class="creation-plan"><div class="row between"><strong>${p.kind==='project'?'创建项目':p.kind==='workspace'?'创建工作区':'创建会话'}</strong><span class="pill">${p.status==='done'?'已模拟创建':p.status==='cancelled'?'已取消':'待确认'}</span></div><dl><dt>名称</dt><dd>${esc(p.name)}</dd><dt>目标 Host</dt><dd>${hostById(p.host).name}${offline?' · 离线':''}</dd><dt>所属项目</dt><dd>${esc(p.kind==='project'?p.name:projectById(p.project).name)}</dd><dt>目录</dt><dd class="mono">${esc(p.path)}</dd><dt>同时准备</dt><dd>${p.kind==='project'?'默认工作空间 + 起始会话':p.kind==='workspace'?'工作区 + 起始会话':'独立会话'}</dd></dl>${p.status==='pending'?`<div class="plan-note">${offline?'目标 Host 离线，请编辑方案选择在线 Host。':!skill?'Paseo 系统操作技能已停用，请先启用。':'通过 Paseo 系统操作技能执行 · 当前仅模拟'}</div><div class="row">${button('execute-plan','模拟创建','check',`data-id="${p.id}" ${offline||!skill?'disabled':''}`,'btn primary small')}${button('edit-plan','编辑方案','edit',`data-id="${p.id}"`,'btn small')}${button('cancel-plan','取消',null,`data-id="${p.id}"`,'btn small quiet')}</div>`:p.status==='done'?`<div class="row">${button('project','查看项目','project',`data-id="${p.resultProject}"`,'btn small')}${button('ai-session','进入新会话','chat',`data-id="${p.resultSession}"`,'btn primary small')}</div>`:''}</section>`;}
function findPlan(id){return state.aiSessions.flatMap(s=>s.messages).find(m=>m.plan?.id===id)?.plan;}
function makePlan(text){const kind=/创建.*项目|新建.*项目/.test(text)?'project':/工作区|工作空间/.test(text)?'workspace':'session';const target=projects.filter(p=>text.toLowerCase().includes(p.name.toLowerCase())).sort((a,b)=>b.name.length-a.name.length)[0]||projectById(state.aiProject)||projects[0];const host=hosts.find(h=>text.toLowerCase().includes(h.name.toLowerCase()))||(text.includes('生产')?hostById('prod'):text.includes('研发服务器')?hostById('dev'):text.includes('边缘')?hostById('edge'):hostById(target.instances[0]));const name=text.match(/[「“"]([^」”"]+)[」”"]/)?.[1]||(kind==='project'?'新项目':kind==='workspace'?'新工作区':'新会话');const slug=name.replace(/[^\p{L}\p{N}_-]/gu,'-').replace(/^-|-$/g,'')||'new-project';return {id:'plan-'+nextId++,kind,name,project:target.id,host:host.id,path:kind==='project'?host.path+'/'+slug:resourcePath(target,host.id),status:'pending'};}
function editPlan(id){const p=findPlan(id);if(!p||p.status!=='pending')return;modal('编辑创建方案','确认目标 Host 与目录后，再模拟执行。',`<form id="plan-form" data-id="${id}"><label class="form-field">名称<input name="name" value="${esc(p.name)}" maxlength="80" required></label>${p.kind!=='project'?`<label class="form-field">所属项目<select name="project">${projects.map(x=>`<option value="${x.id}" ${x.id===p.project?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label>`:''}<label class="form-field">目标 Host<select name="host" id="plan-host">${hosts.map(h=>`<option value="${h.id}" ${h.id===p.host?'selected':''}>${h.name}${h.online?'':' · 离线'}</option>`).join('')}</select></label><label class="form-field">${p.kind==='project'?'项目目录':'项目实例目录'}<input name="path" value="${esc(p.path)}" ${p.kind==='project'?'':'readonly'} required pattern="^(/|~).*"></label></form>`,button('close-modal','取消',null,'','btn small')+'<button class="btn primary small" form="plan-form" type="submit">保存方案</button>');}
function executePlan(id){const plan=findPlan(id);if(!plan||plan.status!=='pending')return;if(!hostById(plan.host).online||!state.skills.find(s=>s.id==='paseo').enabled)return;let p=projectById(plan.project);if(plan.kind!=='project'&&!p.instances.includes(plan.host))return toast('这个项目在目标 Host 上没有实例，请编辑方案');if(plan.kind==='project'&&projects.some(p=>p.instances.includes(plan.host)&&resourcePath(p,plan.host)===plan.path))return toast('该 Host 的目录已有项目，请编辑目录');state.history.push({label:'模拟创建资源',data:snapshot()});if(state.history.length>30)state.history.shift();const sessionId='ai-'+nextId++,workspace=plan.kind==='workspace'?plan.name:plan.kind==='session'?(state.nodes.find(n=>n.kind==='workspace'&&n.project===p.id&&n.host===plan.host)?.name||'默认工作空间'):'默认工作空间';if(plan.kind==='project'){p={id:'project-'+nextId++,name:plan.name,desc:'由个人 AI 创建的演示项目',symbol:plan.name[0].toUpperCase(),color:'blue',tags:['研发'],instances:[plan.host],count:1,branch:'main',path:plan.path.split('/').pop(),rootPath:plan.path};projects.push(p);state.favorites.push(p.id);state.nodes.push({id:'node-'+p.id,kind:'project',name:p.name,project:p.id,parent:nodeById('devcat')?'devcat':null,order:children(nodeById('devcat')?'devcat':null).length});state.collapsed.delete('devcat');}if(plan.kind!=='session'){let parent=state.nodes.find(n=>n.kind==='project'&&n.project===p.id);if(!parent){parent={id:'node-'+p.id,kind:'project',name:p.name,project:p.id,parent:null,order:state.nodes.length};state.nodes.push(parent);}state.nodes.push({id:'workspace-'+nextId++,kind:'workspace',name:workspace,project:p.id,host:plan.host,parent:parent.id,order:children(parent.id).length});state.collapsed.delete(parent.id);if(plan.kind==='workspace')p.count++;}const session={id:sessionId,title:plan.kind==='session'?plan.name:plan.name+' · 开始工作',project:p.id,workspace,host:plan.host,path:plan.path,messages:[]};state.aiSessions.push(session);sessions.unshift({id:sessionId,title:session.title,project:p.id,host:plan.host,time:'刚刚',text:'通过个人 AI 模拟创建，工作空间：'+workspace});plan.status='done';plan.resultProject=p.id;plan.resultSession=sessionId;state.version++;refreshChat();toast('已模拟创建，项目树与会话列表已更新');}
function refreshChat(){render();document.querySelectorAll('.chat-messages').forEach(e=>e.scrollTop=e.scrollHeight);}
function VariantC(){const p=projectById(state.aiProject)||projects[0];return `<div class="home focus-home"><section class="focus-header"><div><div class="eyebrow">FOCUS / THINK / BUILD</div><h1>专注于眼前，连接所有上下文。</h1><p>保持项目在手边，让对话直接推动下一步。</p></div>${button('focus-project','切换引用项目','updown','','btn')}</section><div class="focus-columns"><div class="focus-sheet">${searchBox('focus-search')}<div class="focus-project"><div class="row between"><span class="project-icon ${p.color}">${p.system?icon('sparkle'):esc(p.symbol)}</span><span class="pill accent">${p.system?'默认 AI 项目':'当前引用项目'}</span></div><h2>${esc(p.name)}</h2><p>${esc(p.desc)}</p><div class="project-path">${icon('folder')}<span>${esc(resourcePath(p,p.instances[0]))}</span></div><div class="row">${button(p.system?'system-directory':'project',p.system?'查看系统目录':'进入项目','folder',`data-id="${p.id}"`,'btn small')}${button('navigate','管理技能','grid','data-page="skills"','btn small quiet')}</div></div><div class="section-heading"><h2>这次想完成的事</h2><span class="pill">${state.checklist.filter(Boolean).length} / 3</span></div><ul class="focus-notes">${[['确认布局与皮肤','保留三种视图，选择舒适的工作外观'],['用 AI 创建一个项目','体验 Host → 项目 → 工作区 → Session'],['保持真实资源归属','分类与层级只改变展示关系']].map((x,i)=>`<li><input type="checkbox" data-check="${i}" aria-label="${x[0]}" ${state.checklist[i]?'checked':''}><span class="focus-note-label ${state.checklist[i]?'completed':''}">${x[0]}<small>${x[1]}</small></span></li>`).join('')}</ul><div class="section-heading"><h2>可用技能</h2>${button('navigate','全部技能','arrow','data-page="skills"','btn small quiet')}</div><div class="skill-badges">${state.skills.filter(s=>s.enabled).map(s=>`<button data-action="skill-detail" data-id="s.id">${icon('grid')}${esc(s.name)}</button>`.replace('data-id="s.id"',`data-id="${s.id}"`)).join('')}</div><div class="source-card">先通过原型确认方向，再逐步实现。<small>已确认记忆 · 个人偏好</small></div></div>${chatPanel(true)}</div></div>`;}
function hostsPage(){return `<div class="home"><div class="page-heading"><div><div class="eyebrow">CONNECTED WORLDS</div><h1>不同地方，同一个工作空间。</h1><p>连接只决定可达性，执行前始终核实目标环境。</p></div><span class="pill">3 在线 / 1 离线</span></div><div class="host-grid">${hosts.map(h=>`<article class="host-card"><div class="row between">${icon('server')}<span class="pill"><span class="dot ${h.online?'':'off'}"></span>${h.online?'在线':'离线 · 缓存'}</span></div><h3>${h.name}</h3><p>${h.label} · ${h.network}</p><div class="host-stats"><span><b>${projects.filter(p=>p.instances.includes(h.id)).length}</b> 项目实例</span><span><b>${state.nodes.filter(n=>n.kind==='workspace'&&n.host===h.id).length}</b> 树中工作区</span><span>${h.env}</span></div>${button('host','浏览此 Host','arrow',`data-id="${h.id}"`,'btn small')}</article>`).join('')}</div><div class="info-box" style="margin-top:25px">这里展示 4 个模拟 Host。公网、SSH、VPN 和 Relay 是环境标签，原型不会建立连接。</div></div>`;}
function memoryPage(){return `<div class="home"><div class="page-heading"><div><div class="eyebrow">A MEMORY THAT GROWS WITH YOU</div><h1>把经历，留成下一次的起点。</h1><p>每条记忆都有来源；你决定什么值得留下。</p></div>${button('new-memory','添加记忆','plus','','btn small')}</div><div class="tabs"><button class="tab active">全部记忆 <span class="pill">${state.memories.length}</span></button><span class="muted" style="font-size:12px;margin-left:auto">${state.memories.filter(m=>!m.confirmed).length} 条待确认</span></div>${state.memories.map(m=>`<article class="memory-card"><div class="row"><span class="pill">${esc(m.type)}</span><span class="pill">${esc(m.scope)}</span><span class="muted" style="font-size:12px;margin-left:auto">${m.confirmed?(m.enabled===false?'已停用':'✓ 已确认 · 已启用'):'○ 候选，尚未加入问答上下文'}</span></div><h3>${esc(m.title)}</h3><p>${esc(m.text)}</p><div class="memory-meta"><span>来源：${esc(m.source)}</span>${m.session?`<button data-action="session" data-id="${m.session}">查看来源 ↗</button>`:''}${!m.confirmed?`<button data-action="confirm-memory" data-id="${m.id}">确认保存</button>`:''}${m.confirmed?`<button data-action="toggle-memory" data-id="${m.id}">${m.enabled===false?'启用记忆':'停用记忆'}</button>`:''}<button data-action="remove-memory" data-id="${m.id}" style="margin-left:5px;color:var(--muted)">移除</button></div></article>`).join('')}</div>`;}
function switcher(){return `<nav class="switcher" aria-label="工作台视图切换"><span class="switch-label">工作视图</span>${[['A','搜索工作台','search'],['B','运维控制台','server'],['C','专注空间','sparkle']].map(([v,name,ic])=>`<button class="${state.variant===v?'active':''}" data-action="variant" data-id="${v}" aria-pressed="${state.variant===v}">${icon(ic)}<span>${v} · ${name}</span></button>`).join('')}<button class="state-btn" data-action="state">${icon('layers')}状态 ${state.version}</button></nav>`;}
function render(){document.body.dataset.variant=state.variant;document.body.dataset.skin=state.skin;document.body.dataset.page=state.page;app.innerHTML=`<div class="shell ${state.mobileOpen?'mobile-open':''}">${sidebar()}${state.mobileOpen?'<button class="mobile-shade" data-action="mobile-menu" aria-label="收起导航"></button>':''}<main class="main">${topbar()}<div class="prototype-strip"><span class="dot"></span>交互原型 · 演示资源与模拟 AI<span class="strip-right">布局与皮肤可独立切换</span></div><div class="content">${state.page==='hosts'?hostsPage():state.page==='memory'?memoryPage():state.page==='skills'?skillsPage():state.page==='ai'?aiWorkspace():state.variant==='A'?VariantA():state.variant==='B'?VariantB():VariantC()}</div></main></div>${switcher()}`;document.querySelectorAll('.brand [data-action="mobile-menu"],.breadcrumb [data-action="mobile-menu"]').forEach(b=>b.classList.add('mobile-menu'));if(state.query)renderSearch();if(state.drawer)renderDrawer();}
function setVariant(v){state.variant=v;state.page='home';state.query='';state.searchScope='all';state.drawer=false;overlay.innerHTML='';const url=new URL(location.href);url.searchParams.set('variant',v);history.replaceState(null,'',url);render();console.info('Workbench prototype state',exportState());}
function exportState(){return {...snapshot(),skin:state.skin,scenario:state.scenario,skills:state.skills,aiSessions:state.aiSessions,variant:state.variant,page:state.page,activeTab:state.tab,viewMode:state.mode,showHidden:state.showHidden,collapsed:[...state.collapsed],revision:state.version,aiContext:state.aiProject,checklist:state.checklist,messages:currentSession().messages};}
function modal(title,subtitle,body,footer='',wide=false){state.drawer=false;overlay.innerHTML=`<div class="overlay-backdrop" data-dismiss="true"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><header class="modal-head"><div><h2>${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}</div>${iconButton('close-modal','close','关闭弹窗')}</header><div class="modal-body">${body}</div>${footer?`<footer class="modal-footer">${footer}</footer>`:''}</section></div>`;setTimeout(()=>overlay.querySelector('input:not([type=checkbox]),textarea,select,button')?.focus(),0);}
function closeModal(){overlay.innerHTML='';state.drawer=false;}
function renderDrawer(){overlay.innerHTML=`<div class="drawer-shade">${chatPanel()}</div>`;const messages=overlay.querySelector('.chat-messages');if(messages)messages.scrollTop=messages.scrollHeight;}
function openProject(id){const p=projectById(id);if(!p)return;if(p.system){state.page='ai';closeModal();render();return;}modal(esc(p.name),'一个逻辑项目，多个真实位置。请选择要进入的实例。',`<div class="detail-metric"><div class="metric-cell"><strong>${p.instances.length}</strong><span>Host 实例</span></div><div class="metric-cell"><strong>${p.count}</strong><span>工作区</span></div><div class="metric-cell"><strong>${sessions.filter(s=>s.project===id).length}</strong><span>演示对话</span></div></div><div class="row" style="margin-bottom:18px">${p.tags.map(t=>`<span class="pill">${t}</span>`).join('')}<span class="pill">${icon('branch')}${esc(p.branch)}</span></div>${p.instances.map(hid=>{const h=hostById(hid);return `<div class="instance"><div class="row"><span class="dot ${h.online?'':'off'}"></span><span class="instance-title">${h.name}</span><span class="pill">${h.env}</span>${!h.online?'<span class="offline-note">离线 · 最后缓存</span>':''}</div><div class="path">${esc(resourcePath(p,h.id))}</div>${button('workspace',h.online?'打开工作区':'Host 离线，暂不可进入','arrow',`data-project="${p.id}" data-host="${h.id}" ${h.online?'':'disabled'}`,'btn small')}${button('project-chat','基于此项目提问','sparkle',`data-id="${p.id}"`,'btn small quiet')}</div>`;}).join('')}`,button('close-modal','返回工作台',null,'','btn small'));}
function openWorkspace(project,host,name){const p=projectById(project),h=hostById(host);if(!h.online)return toast('该 Host 离线，可浏览缓存，但不能执行任务');modal(name||p.name+' / 工作区','工作区打开流程预览 · 不会导航到真实 Paseo',`<div class="info-box">即将进入的目标已明确。原型中所有按钮都只改变演示状态。</div><div class="instance"><div class="row"><span class="dot"></span><strong>${h.name}</strong><span class="pill">${h.env}</span></div><div class="path">${esc(resourcePath(p,h.id))}</div><span class="pill">${icon('branch')}${esc(p.branch)}</span></div><div class="detail-section-title">此工作区的上下文</div><p style="font-size:12px;line-height:1.9;color:var(--muted)">项目：${esc(p.name)}<br>目标 Host：${h.name}<br>会话与终端将在这个 Host 上运行。</p>`,button('project-chat','继续到 AI 助手','sparkle',`data-id="${p.id}"`,'btn primary small'));}
function openHost(id){const h=hostById(id);modal(h.name,`${h.label} · ${h.network}`,`<div class="info-box">${h.online?'连接在线，可选择项目或工作区继续。':'当前离线。以下是演示缓存；不会自动切换到其他 Host。'}</div>${projects.filter(p=>p.instances.includes(id)).map(p=>`<button class="result-row" data-action="project" data-id="${p.id}"><span class="project-icon ${p.color}">${esc(p.symbol)}</span><span class="grow"><strong>${esc(p.name)}</strong><small>${esc(resourcePath(p,h.id))}</small></span>${icon('right')}</button>`).join('')}`,button('host-tab','在工作台按此 Host 筛选','grid',`data-id="${id}"`,'btn primary small'));}
function openSession(id){if(state.aiSessions.some(s=>s.id===id)){state.activeSession=id;state.page='ai';closeModal();render();return;}const s=sessions.find(x=>x.id===id);modal(s.title,`${esc(projectById(s.project).name)} · ${hostById(s.host).name} · ${s.time}`,`<div class="message user">${s.id==='s1'?'我想先看交互效果，再决定具体实施方案。':s.title}</div><div class="message assistant"><div class="message-label">${icon('sparkle')}历史对话摘录 · 演示</div>${esc(s.text)}</div><div class="source-card">来源位置：${hostById(s.host).name} / ${esc(projectById(s.project).name)}<small>搜索包含示例对话及本次模拟创建的会话。</small></div>`,button('project-chat','带着上下文继续','chat',`data-id="${s.project}"`,'btn primary small'));}
function createFolder(parent=null){modal('新建分类','分类只组织展示关系，可以继续创建任意层级的子分类。',`<form id="folder-form"><label class="form-field">分类名称<input name="name" required maxlength="80" placeholder="例如：基础环境 / 数据库检修"></label><label class="form-field">放置位置<select name="parent"><option value="">项目空间根目录</option>${state.nodes.filter(n=>n.kind==='category').map(n=>`<option value="${n.id}" ${n.id===parent?'selected':''}>${esc(nodePath(n))}</option>`).join('')}</select></label></form>`,button('close-modal','取消',null,'','btn small')+'<button class="btn primary small" form="folder-form" type="submit">创建分类</button>');}
function nodePath(node){const names=[],seen=new Set();while(node&&!seen.has(node.id)){seen.add(node.id);names.unshift(node.name);node=nodeById(node.parent);}return names.join(' / ');}
function closeMenu(){document.querySelector('#context-menu').hidden=true;}
function showMenu(items,anchor){const menu=document.querySelector('#context-menu');menu.innerHTML=items;menu.hidden=false;const rect=anchor.getBoundingClientRect();menu.style.left=Math.min(rect.right+4,innerWidth-205)+'px';menu.style.top=Math.max(8,Math.min(rect.top,innerHeight-menu.offsetHeight-12))+'px';}
function nodeMenu(id,anchor){const n=nodeById(id);if(!n||n.system)return;const attrs=`data-id="${esc(id)}"`;showMenu([
  button('rename-node','重命名','edit',attrs),button('move-dialog','移动到…','move',attrs),'<div class="menu-rule"></div>',
  ...[['up','上移'],['down','下移'],['top','置顶'],['bottom','置底']].map(([d,t])=>button('sort-node',t,d==='up'||d==='top'?'up':'down',`${attrs} data-dir="${d}"`)),
  '<div class="menu-rule"></div>',button('hide-node',n.hidden?'显示节点':'隐藏整个分支',n.hidden?'eye':'hide',attrs),
  ...(n.kind!=='workspace'?[button('flatten-node',n.flat?'还原节点层级':'合并层级，保留子项','flatten',attrs)]:[]),
  ...(n.kind==='category'?[button('new-folder','新建子分类','plus',attrs),button('delete-node','删除分类，提升子项','trash',attrs)]:[]),
  button('restore-node','恢复此节点默认位置','undo',attrs),
].join(''),anchor);}
function treeMenu(anchor){showMenu([button('toggle-native',state.mode==='custom'?'切回原生视图':'返回自定义视图','grid'),button('show-hidden',state.showHidden?'退出隐藏节点管理':'显示隐藏节点与容器','eye'),button('undo','撤销上一步','undo'),'<div class="menu-rule"></div>',button('reset','重置全部演示状态','undo')].join(''),anchor);}
function moveDialog(id){const n=nodeById(id);modal('移动「'+esc(n.name)+'」','移动只改变展示位置，真实 Host 和文件路径保持不变。',`<form id="move-form" data-id="${id}"><label class="form-field">目标分类<select name="parent"><option value="">项目空间根目录</option>${state.nodes.filter(p=>p.id!==id&&canMove(id,p.id)).map(p=>`<option value="${p.id}" ${p.id===n.parent?'selected':''}>${esc(nodePath(p))}</option>`).join('')}</select></label></form>`,button('close-modal','取消',null,'','btn small')+'<button class="btn primary small" form="move-form" type="submit">移动到这里</button>');}
function addProjects(newTab=false){const tab=state.tabs.find(t=>t.id===state.tab);modal(newTab?'创建自己的项目集合':'添加已有项目',newTab?'按任务或场景组织项目。相同项目可以出现在多个 Tab。':'这里只添加入口，不创建项目，也不改变原生归属。',`<form id="projects-form" data-new-tab="${newTab}">${newTab?'<label class="form-field">Tab 名称<input name="name" required maxlength="30" placeholder="例如：本周重点 / 生产巡检"></label>':''}${!newTab&&tab?.type==='host'?'<div class="info-box">Host Tab 自动按资源归属筛选；本次选择将加入「常用项目」。</div>':''}<div class="picker-filters"><input id="picker-query" aria-label="搜索已有项目" placeholder="搜索名称或路径"><select id="picker-host" aria-label="按 Host 筛选项目"><option value="all">全部 Host</option>${hosts.map(h=>`<option value="${h.id}">${h.name}</option>`).join('')}</select></div>${projects.map(p=>{const selected=!newTab&&(tab?.type==='manual'?tab.projects:state.favorites).includes(p.id);return `<label class="pick-row" data-picker-project="${p.id}"><input type="checkbox" name="project" value="${p.id}" ${selected?'checked':''}><span class="project-icon ${p.color}">${esc(p.symbol)}</span><span class="grow"><strong>${esc(p.name)}</strong><small>${p.instances.map(h=>hostById(h).name).join(' · ')}</small></span></label>`;}).join('')}</form>`,button('close-modal','取消',null,'','btn small')+`<button class="btn primary small" form="projects-form" type="submit">${newTab?'创建 Tab':'保存选择'}</button>`);}
function renderSearch(){const result=document.querySelector('#search-results');if(!result)return;const q=state.query.trim().toLowerCase();if(!q){result.hidden=true;return;}const found=[];projects.forEach(p=>{if([p.name,p.desc,p.path,...p.tags].join(' ').toLowerCase().includes(q))found.push({action:'project',id:p.id,title:p.name,sub:'项目 · '+p.instances.map(h=>hostById(h).name).join(' / '),icon:'project'});});hosts.forEach(h=>{if([h.name,h.label,h.network,h.env].join(' ').toLowerCase().includes(q))found.push({action:'host',id:h.id,title:h.name,sub:'Host · '+(h.online?'在线':'离线缓存')+' · '+h.label,icon:'server'});});[...sessions,...state.aiSessions.filter(a=>!sessions.some(s=>s.id===a.id)).map(a=>({...a,text:a.messages.map(m=>m.text).join(' ')}))].forEach(s=>{if((s.title+' '+s.text).toLowerCase().includes(q))found.push({action:'session',id:s.id,title:s.title,sub:'对话 · '+hostById(s.host).name+' · '+s.text.slice(0,32)+'…',icon:'chat'});});state.memories.filter(m=>m.confirmed).forEach(m=>{if((m.title+m.text).toLowerCase().includes(q))found.push({action:'navigate',id:'memory',title:m.title,sub:'个人记忆 · '+m.scope,icon:'memory'});});const scoped=found.filter(r=>state.searchScope==='all'||(r.action==='navigate'?'memory':r.action)===state.searchScope);found.splice(0,found.length,...scoped);result.hidden=false;result.innerHTML=`<div class="result-heading">${found.length} 条结果 · 项目、Host、对话与已确认记忆</div>${found.length?found.map(r=>`<button class="result-row" data-action="${r.action}" data-id="${r.id}" ${r.action==='navigate'?'data-page="memory"':''}>${icon(r.icon)}<span class="grow"><strong>${esc(r.title)}</strong><small>${esc(r.sub)}</small></span>${icon('right')}</button>`).join(''):'<div class="empty">没有找到匹配内容<br>可以试试「支付」「工作台」或「生产」</div>'}<button class="result-row" data-action="ask" data-text="${esc(state.query)}">${icon('sparkle')}<span class="grow">带着这个问题，询问 AI 助手</span>${icon('arrow')}</button>`;}
function ask(text){text=text.trim();if(!text)return;currentSession().messages.push({role:'user',text});if(/创建|新建/.test(text)&&/项目|工作区|工作空间|会话|session/i.test(text)){currentSession().messages.push({role:'assistant',text:'已整理为下面的创建方案。你可以编辑名称、Host 与目录，再模拟创建。',plan:makePlan(text)});if(state.page!=='ai'&&!(state.variant==='C'&&state.page==='home'))state.drawer=true;refreshChat();return;}let answer,source;
  if(/生产|检查|环境|巡检|服务器/.test(text)){source='s3';answer='可以先从这三步开始：\n\n1. 核对目标 Host、项目与工作目录。\n2. 检查连接状态，再查看服务日志与最近变更。\n3. 在测试环境验证操作步骤，随后再安排生产变更。\n\n注意：Edge Node 当前离线，原型不会把任务自动转交给其他 Host。';}
  else if(/区别|不同|Host|host|分布/.test(text)){const p=projectById(state.aiProject)||projects[0];source='s1';answer=`「${esc(p.name)}」在 ${p.instances.map(h=>hostById(h).name).join('、')} 上有独立实例。\n\n它们共享逻辑项目名称，但目录、工作区与对话各自独立。打开项目卡片后，可以明确选择要进入的 Host。\n\n树中的移动只调整展示关系，不会移动这些实例。`;}
  else if(/上次|工作台|原型|设计/.test(text)){source='s1';answer='我们停在「先确认交互效果，再实施」这一步。\n\n已经明确的方向：\n• 分类可以无限嵌套，项目可以合并展示层级。\n• 同一项目的不同 Host 实例保留独立身份。\n• 搜索、项目入口与个人记忆集中在工作台。\n\n现在可以比较底部的三种布局，再选出最适合你的组合。';}
  else {source='s1';answer='这是交互原型中的示例回答，尚未连接真实 AI 模型。\n\n正式实现会先检索当前项目、历史会话和已确认记忆，再附带来源回答你的问题。\n\n你可以试着询问「我们上次讨论到哪里了」或「生产环境检查清单」，体验两条完整的示例流程。';}
  currentSession().messages.push({role:'assistant',text:answer,source});state.query='';if(state.page==='ai'||(state.variant==='C'&&state.page==='home')){state.drawer=false;overlay.innerHTML='';render();const el=document.querySelector('.chat-messages');if(el)el.scrollTop=el.scrollHeight;}else{state.drawer=true;renderDrawer();}}
function saveMemory(index){const m=currentSession().messages[index];if(!m||m.saved)return;modal('保存为记忆候选','先核对内容与来源，候选记忆需确认后才进入问答上下文。',`<form id="memory-form" data-message="${index}"><label class="form-field">标题<input name="title" required maxlength="80" value="${esc(m.source==='s3'?'生产环境检查约定':'工作台设计与组织约定')}"></label><label class="form-field">内容<textarea name="text" required rows="6">${esc(m.text)}</textarea></label><span class="pill">来源：${sessions.find(s=>s.id===m.source).title}</span></form>`,button('close-modal','取消',null,'','btn small')+'<button class="btn primary small" form="memory-form" type="submit">保存候选</button>');}
function help(){modal('先体验，再决定','这是用于选择设计方向的独立原型。',`<div class="info-box">三种方案共享演示状态。切换布局后，你整理过的分类、收藏和 Tab 都会保留；刷新页面则恢复初始演示。</div><p style="font-size:12px;line-height:2.2">① 底部切换 A / B / C，比较信息布局。<br>② 左侧拖动节点，或点击 ··· 移动、隐藏、排序、合并层级。<br>③ 直接切换原生视图，或保存与恢复展示快照。<br>④ 搜索「支付」「工作台」，查看项目与对话。<br>⑤ 打开项目，选择明确的 Host 实例。<br>⑥ 在 AI 工作空间创建项目、工作区与会话，或管理预装与自定义技能。<br>⑦ 右上角切换四套皮肤，布局和数据会保留。</p>`,button('close-modal','开始体验','arrow','','btn primary small'));}
function performAction(el){const a=el.dataset.action,id=el.dataset.id;closeMenu();
  switch(a){
    case 'view-mode':state.mode=el.dataset.mode;render();break;
    case 'search-scope':state.searchScope=id;render();document.querySelector('#search-input')?.focus();break;
    case 'ops-mode':state.opsMode=id;render();break;
    case 'skins':modal('选择工作台皮肤','皮肤只改变外观，A / B / C 布局和当前数据会保留。',`<div class="skin-grid">${skins.map(s=>`<button class="skin-option ${state.skin===s.id?'selected':''}" data-action="set-skin" data-id="${s.id}"><div class="skin-swatch">${s.colors.map(c=>`<i style="background:${c}"></i>`).join('')}</div><strong>${s.name}</strong><small>${s.desc}</small></button>`).join('')}</div>`);break;
    case 'set-skin':state.skin=id;{const u=new URL(location.href);u.searchParams.set('skin',id);history.replaceState(null,'',u);}closeModal();render();break;
    case 'system-directory':systemDirectory();break;
    case 'context-preview':contextPreview();break;
    case 'skill-detail':skillDetail(id);break;
    case 'toggle-skill':{const s=state.skills.find(s=>s.id===id);s.enabled=!s.enabled;closeModal();render();toast(s.enabled?'技能已启用':'技能已停用');break;}
    case 'add-skill':modal('添加自定义技能','先为未来的技能定义一个位置；当前仅演示，不写入磁盘。','<form id="skill-form"><label class="form-field">技能名称<input name="name" required maxlength="60" placeholder="例如：代码审查"></label><label class="form-field">目录名称<input name="slug" required pattern="[a-z0-9-]+" maxlength="50" placeholder="code-review"></label><label class="form-field">能力描述<textarea name="desc" required rows="3" placeholder="描述这个技能可以完成的工作"></textarea></label></form>','<button class="btn primary small" type="submit" form="skill-form">添加技能</button>');break;
    case 'ai-session':state.activeSession=id;state.aiProject=currentSession().project;state.page='ai';closeModal();render();break;
    case 'new-chat':{const id='ai-'+nextId++;state.aiSessions.push({id,title:'新的对话',project:'assistant',workspace:'默认工作空间',host:'mac',path:SYSTEM_ROOT,messages:[]});state.activeSession=id;state.aiProject='assistant';render();break;}
    case 'execute-plan':executePlan(id);break;
    case 'edit-plan':editPlan(id);break;
    case 'cancel-plan':findPlan(id).status='cancelled';refreshChat();break;
    case 'save-snapshot':modal('树与 Tab 的快照','保存当前展示配置，之后可恢复。项目与会话资源不会被删除。',`<div class="info-box">${state.snapshot?'已有本次体验的快照，可以恢复或覆盖。':'还没有快照。保存后可继续体验隐藏、排序与层级合并。'}</div>`,button('capture-snapshot',state.snapshot?'覆盖快照':'保存快照','clock','','btn primary small')+(state.snapshot?button('restore-snapshot','恢复快照','undo','','btn small'):''));break;
    case 'capture-snapshot':state.snapshot=structuredClone({nodes:state.nodes,tabs:state.tabs,favorites:state.favorites});closeModal();toast('展示配置快照已保存');break;
    case 'restore-snapshot':{const snap=structuredClone(state.snapshot);const newer=state.nodes.filter(n=>n.kind!=='category'&&!snap.nodes.some(x=>x.id===n.id));state.nodes=[...snap.nodes,...newer.map(n=>({...n,parent:snap.nodes.some(x=>x.id===n.parent)||newer.some(x=>x.id===n.parent)?n.parent:null}))];state.tabs=snap.tabs;state.favorites=snap.favorites;state.tab='favorites';closeModal();render();toast('已恢复展示快照，新增资源保留');break;}
    case 'toggle-memory':{const m=state.memories.find(m=>m.id===id);m.enabled=m.enabled===false;render();break;}
    case 'navigate':state.page=el.dataset.page;state.mobileOpen=false;state.query='';closeModal();render();break;
    case 'variant':setVariant(id);break;
    case 'variant-prev':case 'variant-next':setVariant(['A','B','C'][(['A','B','C'].indexOf(state.variant)+(a==='variant-next'?1:2))%3]);break;
    case 'tab':state.tab=id;render();break;
    case 'new-tab':addProjects(true);break;
    case 'add-project':addProjects(false);break;
    case 'project':openProject(id);break;
    case 'host':openHost(id);break;
    case 'session':openSession(id);break;
    case 'workspace':openWorkspace(el.dataset.project,el.dataset.host);break;
    case 'favorite':if(projectById(id)?.system)return;mutate(state.favorites.includes(id)?'已取消收藏':'已加入常用项目',()=>{state.favorites=state.favorites.includes(id)?state.favorites.filter(x=>x!==id):[...state.favorites,id];});break;
    case 'host-tab':if(!state.tabs.some(t=>t.id===id))state.tabs.push({id,name:hostById(id).name,type:'host',icon:'server'});state.tab=id;state.page='home';closeModal();render();break;
    case 'query-hosts':state.page='hosts';render();break;
    case 'query':state.query=el.dataset.value;render();document.querySelector('#search-input')?.focus();break;
    case 'collapse':if(state.collapsed.has(id)){state.collapsed.delete(id);}else{state.collapsed.add(id);}render();break;
    case 'node-open':{const n=(state.mode==='native'?nativeNodes():state.nodes).find(n=>n.id===id);if(n?.system||n?.project==='assistant'){state.page='ai';render();}else if(n?.kind==='category'){if(state.collapsed.has(id)){state.collapsed.delete(id);}else{state.collapsed.add(id);}render();}else if(n?.kind==='project')openProject(n.project);else if(n)openWorkspace(n.project,n.host,n.name);break;}
    case 'node-menu':nodeMenu(id,el);break;
    case 'tree-menu':treeMenu(el);break;
    case 'new-folder':createFolder(id||null);break;
    case 'rename-node':{const n=nodeById(id);modal('重命名节点','只修改工作台中的显示名称。',`<form id="rename-form" data-id="${id}"><label class="form-field">显示名称<input name="name" value="${esc(n.name)}" required maxlength="80"></label></form>`,'<button class="btn primary small" form="rename-form" type="submit">保存名称</button>');break;}
    case 'move-dialog':moveDialog(id);break;
    case 'sort-node':sortNode(id,el.dataset.dir);break;
    case 'hide-node':mutate(nodeById(id).hidden?'已显示节点':'已隐藏分支',()=>nodeById(id).hidden=!nodeById(id).hidden);break;
    case 'flatten-node':mutate(nodeById(id).flat?'已恢复节点层级':'已合并层级，保留子项',()=>{nodeById(id).flat=!nodeById(id).flat;state.collapsed.delete(id);});break;
    case 'delete-node':mutate('已删除分类，子项提升到上一层',()=>{const n=nodeById(id);children(id).forEach(c=>{c.parent=n.parent;c.order=children(n.parent).length;});state.nodes=state.nodes.filter(x=>x.id!==id);});break;
    case 'restore-node':{const original=initialNodes.find(n=>n.id===id);if(!original)return toast('自建节点没有原生位置，可使用“移动到”');mutate('已恢复默认展示位置',()=>{const n=nodeById(id);n.parent=nodeById(original.parent)?original.parent:null;n.order=original.order;delete n.hidden;delete n.flat;});break;}
    case 'toggle-native':state.mode=state.mode==='custom'?'native':'custom';render();toast(state.mode==='native'?'已切回原生视图，自定义配置已保留':'已恢复你的自定义视图');break;
    case 'show-hidden':state.showHidden=!state.showHidden;render();break;
    case 'undo':undo();break;
    case 'reset':modal('重置演示状态','恢复最初的分类、Tab 和记忆；仅影响这个原型。','<p style="font-size:12px;color:var(--muted)">当前体验中的修改会清空，真实 Paseo 数据不受影响。</p>',button('close-modal','保留当前状态',null,'','btn small')+button('confirm-reset','重置演示','undo','','btn primary small'));break;
    case 'confirm-reset':location.reload();break;
    case 'assistant':if(state.variant==='C'&&state.page==='home'){document.querySelector('#chat-input')?.focus();}else{state.drawer=true;renderDrawer();}break;
    case 'project-chat':state.aiProject=id;if(state.variant==='C'&&state.page==='home'){closeModal();render();document.querySelector('#chat-input')?.focus();}else{state.drawer=true;renderDrawer();}break;
    case 'ask':ask(el.dataset.text||'我们上次讨论到哪里了？');break;
    case 'close-drawer':case 'close-modal':closeModal();break;
    case 'save-memory':saveMemory(Number(el.dataset.index));break;
    case 'confirm-memory':mutate('已确认记忆',()=>state.memories.find(m=>m.id===id).confirmed=true);break;
    case 'remove-memory':mutate('已移除记忆',()=>state.memories=state.memories.filter(m=>m.id!==id));break;
    case 'new-memory':modal('添加个人记忆','记录一条值得在未来使用的偏好、事实或操作约定。','<form id="memory-form"><label class="form-field">标题<input name="title" required maxlength="80" placeholder="例如：我习惯的工作方式"></label><label class="form-field">内容<textarea name="text" required rows="5" placeholder="记录清晰、具体且可复用的内容…"></textarea></label></form>','<button class="btn primary small" form="memory-form" type="submit">保存候选</button>');break;
    case 'focus-project':modal('选择专注的项目','项目选择同时更新 AI 助手的上下文。',projects.map(p=>`<button class="result-row" data-action="set-focus" data-id="${p.id}"><span class="project-icon ${p.color}">${esc(p.symbol)}</span><span class="grow"><strong>${esc(p.name)}</strong><small>${esc(p.desc)}</small></span>${icon('right')}</button>`).join(''));break;
    case 'set-focus':state.aiProject=id;closeModal();render();break;
    case 'mobile-menu':state.mobileOpen=!state.mobileOpen;render();break;
    case 'help':help();break;
    case 'state':modal('原型状态','用于比较设计时检查交互结果。状态只保存在当前页面内存中。',`<pre style="font-size:12px;line-height:1.7;white-space:pre-wrap;overflow-wrap:anywhere;margin:0">${esc(JSON.stringify(exportState(),null,2))}</pre>`,button('close-modal','返回体验',null,'','btn primary small'),true);break;
  }
}
document.addEventListener('click',e=>{const target=e.target.closest('[data-action]');if(target){e.preventDefault();performAction(target);return;}if(e.target.classList.contains('overlay-backdrop')||e.target.classList.contains('drawer-shade'))closeModal();if(!e.target.closest('#context-menu'))closeMenu();if(!e.target.closest('.search-wrap')){const results=document.querySelector('#search-results');if(results)results.hidden=true;}});
function filterPicker(){const q=document.querySelector('#picker-query')?.value.toLowerCase()||'',h=document.querySelector('#picker-host')?.value||'all';document.querySelectorAll('[data-picker-project]').forEach(row=>{const p=projectById(row.dataset.pickerProject);row.hidden=!((p.name+' '+p.path).toLowerCase().includes(q)&&(h==='all'||p.instances.includes(h)));});}
document.addEventListener('input',e=>{if(e.target.id==='picker-query')filterPicker();if(e.target.id==='search-input'){state.query=e.target.value;renderSearch();}});
document.addEventListener('change',e=>{if(e.target.id==='picker-host')filterPicker();if(e.target.id==='scenario-select'){state.scenario=e.target.value;render();}if(e.target.closest('#plan-form')&&e.target.matches('select')){const f=e.target.closest('form'),p=findPlan(f.dataset.id),project=projectById(f.elements.project?.value||p.project),host=f.elements.host.value;f.elements.path.value=p.kind==='project'?hostById(host).path+'/'+p.path.split('/').pop():resourcePath(project,host);}if(e.target.id==='ai-context'){state.aiProject=e.target.value;if(state.variant==='C'&&!state.drawer)render();}if(e.target.dataset.check!==undefined){state.checklist[Number(e.target.dataset.check)]=e.target.checked;render();}});
document.addEventListener('submit',e=>{e.preventDefault();const form=e.target,data=new FormData(form);
  if(form.id==='skill-form'){if(!String(data.get('name')).trim()||!String(data.get('desc')).trim())return toast('请填写技能名称和描述');const slug=String(data.get('slug')).trim();if(state.skills.some(s=>s.slug===slug))return toast('这个技能目录已存在');state.skills.push({id:'skill-'+nextId++,name:String(data.get('name')).trim(),slug,desc:String(data.get('desc')).trim(),enabled:true,builtin:false});closeModal();render();toast('已添加技能演示定义');}
  if(form.id==='plan-form'){if(!String(data.get('name')).trim())return toast('请输入名称');const p=findPlan(form.dataset.id);Object.assign(p,{name:String(data.get('name')).trim(),host:data.get('host'),path:String(data.get('path')).trim(),project:data.get('project')||p.project});if(p.kind!=='project'&&!projectById(p.project).instances.includes(p.host))return toast('此项目在该 Host 没有实例，请选择匹配的 Host');closeModal();state.page='ai';refreshChat();}
  if(form.id==='global-search'){renderSearch();if(!state.query.trim())document.querySelector('#search-input')?.focus();}
  if(form.id==='chat-form')ask(form.querySelector('textarea').value);
  if(form.id==='folder-form'){const name=String(data.get('name')).trim();if(!name)return;mutate('已创建分类',()=>{const parent=data.get('parent')||null;state.nodes.push({id:'custom-'+nextId++,kind:'category',name,parent,order:children(parent).length});if(parent)state.collapsed.delete(parent);state.mode='custom';});closeModal();}
  if(form.id==='rename-form'){const name=String(data.get('name')).trim();if(!name)return;mutate('已重命名节点',()=>nodeById(form.dataset.id).name=name);closeModal();}
  if(form.id==='move-form'){moveNode(form.dataset.id,data.get('parent')||null);closeModal();}
  if(form.id==='projects-form'){const selected=data.getAll('project');if(form.dataset.newTab==='true'){const name=String(data.get('name')).trim();if(!name)return;mutate('已创建项目 Tab',()=>{const id='tab-'+nextId++;state.tabs.push({id,name,type:'manual',projects:selected,icon:'folder'});state.tab=id;});}else mutate('已更新项目集合',()=>{const tab=state.tabs.find(t=>t.id===state.tab);if(tab.type==='manual')tab.projects=selected;else{state.favorites=[...new Set(['assistant',...selected])];state.tab='favorites';}});closeModal();}
  if(form.id==='memory-form'){const title=String(data.get('title')).trim(),text=String(data.get('text')).trim();if(!title||!text)return;const msg=form.dataset.message!==undefined?currentSession().messages[Number(form.dataset.message)]:null;mutate('已保存记忆候选',()=>{state.memories.unshift({id:'memory-'+nextId++,title,text,type:'记忆候选',scope:projectById(state.aiProject)?.name||'个人',source:msg?sessions.find(s=>s.id===msg.source).title:'手动记录',session:msg?.source,confirmed:false});if(msg)msg.saved=true;});closeModal();state.page='memory';render();}
});
document.addEventListener('keydown',e=>{const editing=e.target.matches('input,textarea,select,[contenteditable="true"]');if(e.key==='Escape'){closeModal();closeMenu();state.query='';const r=document.querySelector('#search-results');if(r)r.hidden=true;if(state.mobileOpen){state.mobileOpen=false;render();}}
  if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();if(state.page!=='home'){state.page='home';render();}document.querySelector('#search-input')?.focus();}
  if(!editing&&!overlay.innerHTML&&(e.key==='ArrowLeft'||e.key==='ArrowRight')){e.preventDefault();setVariant(['A','B','C'][(['A','B','C'].indexOf(state.variant)+(e.key==='ArrowRight'?1:2))%3]);}
  if(!editing&&(e.key==='Enter'||e.key===' ')&&e.target.matches('[role="button"][data-action]')){e.preventDefault();performAction(e.target);}
});
document.addEventListener('dragstart',e=>{const row=e.target.closest('[data-node]');if(!row||state.mode!=='custom'||nodeById(row.dataset.node)?.system)return;dragId=row.dataset.node;e.dataTransfer.setData('text/plain',dragId);e.dataTransfer.effectAllowed='move';closeMenu();});
function dropTarget(e){const row=e.target.closest('[data-node]');if(!row||!dragId||row.dataset.node===dragId)return null;const target=nodeById(row.dataset.node);if(!target)return null;const box=row.getBoundingClientRect(),ratio=(e.clientY-box.top)/box.height;const inside=ratio>.25&&ratio<.75&&canMove(dragId,target.id);return {row,target,position:inside?'inside':ratio<.5?'before':'after'};}
function clearDrop(){document.querySelectorAll('.drop-inside,.drop-before,.drop-after').forEach(el=>el.classList.remove('drop-inside','drop-before','drop-after'));}
document.addEventListener('dragover',e=>{const drop=dropTarget(e);clearDrop();if(!drop)return;const parent=drop.position==='inside'?drop.target.id:drop.target.parent;if(!canMove(dragId,parent))return;e.preventDefault();e.dataTransfer.dropEffect='move';drop.row.classList.add('drop-'+drop.position);});
document.addEventListener('drop',e=>{const drop=dropTarget(e);clearDrop();if(!drop)return;e.preventDefault();const source=dragId;dragId=null;if(drop.position==='inside')moveNode(source,drop.target.id);else{const siblings=children(drop.target.parent).filter(n=>n.id!==source),idx=siblings.findIndex(n=>n.id===drop.target.id);moveNode(source,drop.target.parent,drop.position==='before'?drop.target.id:siblings[idx+1]?.id);}});
document.addEventListener('dragend',()=>{dragId=null;clearDrop();});
window.addEventListener('popstate',()=>{const v=new URLSearchParams(location.search).get('variant');if(['A','B','C'].includes(v)){state.variant=v;render();}});
render();
console.info('Workbench prototype ready',exportState());
